import path from 'path';
import { writeTextFile } from './files.js';

export function generatedFileHeader({ source, generatedAt = new Date().toISOString() }) {
  return [
    '// Generated by PrismGB tooling.',
    `// Source: ${source}`,
    `// Generated at: ${generatedAt}`,
    ''
  ].join('\n');
}

export function writeGeneratedArtifact({ outputRoot, relativePath, contents }) {
  const outputPath = path.join(outputRoot, relativePath);
  writeTextFile(outputPath, contents);
  return outputPath;
}

